	hEq(t, "prefix or word", ix.SearchAny("qui* zebra"), []Hit{{"b", 2}, {"a", 1}})
	hEq(t, "prefix or prefix", hIDs(ix.SearchAny("fri* afte*")), []string{"c", "d"})
}

func TestStopwordsComeBeforeStemming(t *testing.T) {
