	hEq(t, "ties by id", ix.Search("the"), []Hit{{"a", 2}, {"c", 2}})
	hEq(t, "brown dog", ix.Search("brown dog"), []Hit{{"a", 2}, {"b", 2}})
	hEq(t, "repeated query word counts once", ix.Search("fox fox"), ix.Search("fox"))
